（10分）在一个数据库中，相关表的建表语句如下
 create table T1(
 a1 int primary key,
 a2 int,
 a3 int foreign key references T2(a3)
 );
 create table T2(

 a3 int primary key,
 a4 int,
 a5 int foreign key references T2(a3)
 );
 create table T3(
 a6 int primary key,
 a7 int
 );
 create table T4(
 a1 int foreign key references T1(a1),
 a3 int foreign key references T2(a3),
 a6 int foreign key references T3(a6),
 a8 int,
 primary key (a1, a3, a6)
 );

